using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with default reflection-based metadata
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// --- 1. Strongly-typed metadata: GetTypeInfo(typeof(T)) returns JsonTypeInfo,
//        which you can cast to JsonTypeInfo<T>.
var typedInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Typed info kind : {typedInfo.Kind}");        // Object
Console.WriteLine($"Typed info type : {typedInfo.Type.Name}");   // Person

// Round-trip with the typed metadata
var json = JsonSerializer.Serialize(new Person("Alice", 30), typedInfo);
Console.WriteLine($"Serialized      : {json}");

Person p = JsonSerializer.Deserialize(json, typedInfo)!;
Console.WriteLine($"Deserialized    : {p}");

// --- 2. Probe without throwing: TryGetTypeInfo (added in .NET 9)
//        Returns false instead of throwing if the resolver can't handle the type.
var emptyOptions = new JsonSerializerOptions
{
    // Resolver that only knows about int — Person will not be resolvable.
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new BuiltInIntOnlyResolver())
};

bool found = emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info);
Console.WriteLine($"\nTryGet Person   : found={found}, info={info?.Type.Name ?? "(null)"}");

found = emptyOptions.TryGetTypeInfo(typeof(int), out info);
Console.WriteLine($"TryGet int      : found={found}, info={info?.Type.Name ?? "(null)"}");

// ---------- helper types ----------

record Person(string Name, int Age);

// Minimal resolver that only provides metadata for System.Int32
sealed class BuiltInIntOnlyResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) =>
        type == typeof(int) ? JsonMetadataServices.CreateValueInfo<int>(options, JsonMetadataServices.Int32Converter)
                            : null;
}

